import sys

def solve():
    try:
        line = sys.stdin.read().strip()
        if not line:
            return
        n = int(line)
    except ValueError:
        return

    height = 0
    cubes_used = 0
    current_level_cubes = 0

    while True:
        # For the next level (height + 1), we need 1 + 2 + ... + (height + 1) cubes
        # But we only add them if we have enough remaining cubes
        next_level_cubes = (height + 1) * (height + 2) // 2

        if cubes_used + next_level_cubes <= n:
            cubes_used += next_level_cubes
            height += 1
            current_level_cubes = next_level_cubes
        else:
            break

    print(height)

if __name__ == "__main__":
    solve()

